import RNA, random, sys, multiprocessing as mp

target = "((....))..(...(...(..(.(..(...(((.(((...((((....)))).((((((.((((((.((((((.((((((.((((((((((.((((((.(((((.((((.((((..((((...)))).))).)))))).))))).)))))).)))))))).)))))).)))))).)))))).))))))).)))...(((.(((((.(..((((.(..((((.(..((((.(..(((((((.((((((.(((((.((((((.(((.((((((....))))))..)))).)))).))))).)))))).)))))))).)..)))).)..)))).)..)))).)..))))).((((....))))...))).)))...)..).)..)...)...)..((....))"

stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
pairlist=[(i,j) for i,j in pairs.items() if i<j]
pb=set(pairlist)

def bpd(a):
    pa=set(); st=[]
    for i,c in enumerate(a):
        if c=='(': st.append(i)
        elif c==')': pa.add((st.pop(),i))
    return pa

def fold_dist(seq):
    fc=RNA.fold_compound(seq)
    ss,_=fc.mfe()
    return len(bpd(ss)^pb)

def make_seed(seed):
    r=random.Random(seed)
    seq=['A']*400
    # pair assignment with diversity
    for idx,(i,j) in enumerate(pairlist):
        choice=r.choice([('G','C'),('C','G'),('G','C'),('A','U'),('C','G'),('G','C')])
        seq[i]=choice[0]; seq[j]=choice[1]
    # hairpin caps
    for (i,j) in pairlist:
        inner_unpaired=all(k not in pairs for k in range(i+1,j))
        if inner_unpaired:
            L=j-i-1
            if L==4: cap="GAAA"
            elif L==3: cap="GAA"
            else: cap="A"*L
            for k,ch in enumerate(cap): seq[i+1+k]=ch
            seq[i]='G'; seq[j]='C'
    return ''.join(seq)

def worker(seed, iters=4000):
    r=random.Random(seed*7919+13)
    s=list(make_seed(seed))
    d=fold_dist(''.join(s))
    best=s[:]; bestd=d
    for it in range(iters):
        cand=s[:]
        # mutate: pick random pair region - either flip a pair's bases or change unpaired
        if r.random()<0.7 and pairlist:
            i,j=r.choice(pairlist)
            # flip pair composition but keep complementary
            opts=[('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
            b=r.choice(opts)
            cand[i]=b[0]; cand[j]=b[1]
        else:
            p=r.randint(0,399)
            cand[p]=r.choice("ACGU")
        cs=''.join(cand)
        nd=fold_dist(cs)
        if nd<=d or r.random()<0.05:
            if nd<d or r.random()<0.2:
                s=cand; d=nd
                if d<bestd:
                    best=cand[:]; bestd=nd
        if bestd==0: break
    return bestd, ''.join(best)

if __name__=='__main__':
    N=200
    with mp.Pool(200) as p:
        results=p.map(worker, range(N))
    results.sort(key=lambda x:x[0])
    print("best bp_dist", results[0][0])
    print(results[0][1])
    # save top 3
    for d,s in results[:3]:
        print(d, s)
